CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE projects (id TEXT PRIMARY KEY, path TEXT NOT NULL UNIQUE, label TEXT NOT NULL, config_version INTEGER NOT NULL DEFAULT 1 CHECK(config_version > 0), created_at TEXT NOT NULL);
CREATE TABLE actor_sessions (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('operator','agent')), capability_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE participants (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), alias TEXT NOT NULL, role TEXT NOT NULL, adapter TEXT NOT NULL CHECK(adapter IN ('opencode-glm-plan','codex-chatgpt-astra')), model TEXT NOT NULL, config_version INTEGER NOT NULL DEFAULT 1, enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), UNIQUE(project_id,alias));
CREATE TABLE threads (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, task_ids TEXT NOT NULL CHECK(json_valid(task_ids)), mode TEXT NOT NULL CHECK(mode IN ('brainstorm','independent')), status TEXT NOT NULL CHECK(status IN ('open','waiting_for_input','resolved','archived')), question_id TEXT, latest_human_id TEXT, context_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,id));
CREATE TABLE messages (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, project_id TEXT NOT NULL, thread_id TEXT NOT NULL, author_id TEXT NOT NULL, author_name TEXT NOT NULL, author_role TEXT NOT NULL CHECK(author_role IN ('operator','agent','consultant')), kind TEXT NOT NULL CHECK(kind IN ('message','question','answer','needs_context','abstain','objection','unknown','conclusion','experiment','correction')), body TEXT NOT NULL, reply_to TEXT REFERENCES messages(id), job_id TEXT UNIQUE, basis_context_version INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(project_id,thread_id) REFERENCES threads(project_id,id), UNIQUE(project_id,id));
CREATE TRIGGER messages_immutable_update BEFORE UPDATE ON messages BEGIN SELECT RAISE(ABORT,'messages are immutable'); END;
CREATE TRIGGER messages_immutable_delete BEFORE DELETE ON messages BEGIN SELECT RAISE(ABORT,'messages are immutable'); END;
CREATE VIRTUAL TABLE messages_fts USING fts5(body, content='messages', content_rowid='seq');
CREATE TRIGGER messages_fts_insert AFTER INSERT ON messages BEGIN INSERT INTO messages_fts(rowid,body) VALUES(new.seq,new.body); END;
CREATE TABLE sources (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, thread_id TEXT NOT NULL, path TEXT NOT NULL, revision TEXT, working_tree INTEGER NOT NULL CHECK(working_tree IN (0,1)), blob_hash TEXT NOT NULL, size INTEGER NOT NULL CHECK(size >= 0), required INTEGER NOT NULL CHECK(required IN (0,1)), created_at TEXT NOT NULL, FOREIGN KEY(project_id,thread_id) REFERENCES threads(project_id,id), UNIQUE(project_id,id));
CREATE TABLE message_refs (project_id TEXT NOT NULL, message_id TEXT NOT NULL, ref_id TEXT NOT NULL, ref_kind TEXT NOT NULL CHECK(ref_kind IN ('source','message','decision','constraint')), FOREIGN KEY(project_id,message_id) REFERENCES messages(project_id,id), PRIMARY KEY(message_id,ref_id));
CREATE TABLE decisions (id TEXT PRIMARY KEY, stable_id TEXT NOT NULL, version INTEGER NOT NULL CHECK(version > 0), project_id TEXT NOT NULL, thread_id TEXT NOT NULL, statement TEXT NOT NULL, rationale TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('proposed','accepted','rejected','superseded')), citations TEXT NOT NULL CHECK(json_valid(citations)), actor_id TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(project_id,thread_id) REFERENCES threads(project_id,id), UNIQUE(project_id,stable_id,version));
CREATE TABLE constraints (id TEXT PRIMARY KEY, stable_id TEXT NOT NULL, version INTEGER NOT NULL CHECK(version > 0), project_id TEXT NOT NULL, thread_id TEXT NOT NULL, body TEXT NOT NULL, source_message_id TEXT NOT NULL REFERENCES messages(id), status TEXT NOT NULL CHECK(status IN ('active','superseded')), actor_id TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(project_id,thread_id) REFERENCES threads(project_id,id), UNIQUE(project_id,stable_id,version));
CREATE TABLE jobs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, thread_id TEXT NOT NULL, participant_id TEXT NOT NULL REFERENCES participants(id), causal_key TEXT NOT NULL, question_id TEXT NOT NULL REFERENCES messages(id), boundary_seq INTEGER NOT NULL, context_version INTEGER NOT NULL, round INTEGER NOT NULL DEFAULT 0 CHECK(round BETWEEN 0 AND 1), status TEXT NOT NULL CHECK(status IN ('queued','preparing','running','succeeded','failed','cancelled','interrupted_unknown','needs_scoping','auth_required','quota_wait','disabled')), packet_hash TEXT, config_hash TEXT, requested_model TEXT NOT NULL, reply_id TEXT REFERENCES messages(id), stale_context INTEGER NOT NULL DEFAULT 0 CHECK(stale_context IN (0,1)), error_code TEXT, error_message TEXT, cancel_requested INTEGER NOT NULL DEFAULT 0, parent_job_id TEXT REFERENCES jobs(id), usage TEXT CHECK(usage IS NULL OR json_valid(usage)), retrieval TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(retrieval)), started_at TEXT, completed_at TEXT, created_at TEXT NOT NULL, FOREIGN KEY(project_id,thread_id) REFERENCES threads(project_id,id), UNIQUE(project_id,causal_key));
CREATE TABLE job_events (seq INTEGER PRIMARY KEY AUTOINCREMENT, job_id TEXT NOT NULL REFERENCES jobs(id), event TEXT NOT NULL, details TEXT NOT NULL CHECK(json_valid(details)), created_at TEXT NOT NULL);
CREATE TABLE worker_claim (singleton INTEGER PRIMARY KEY CHECK(singleton=1), job_id TEXT NOT NULL REFERENCES jobs(id), owner_pid INTEGER NOT NULL, owner_identity TEXT NOT NULL, child_pid INTEGER, child_identity TEXT, heartbeat TEXT NOT NULL);
CREATE TABLE budget_ledger (job_id TEXT PRIMARY KEY REFERENCES jobs(id), day TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('reserved','started','released')), policy_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE read_cursors (project_id TEXT NOT NULL, thread_id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actor_sessions(id), through_seq INTEGER NOT NULL CHECK(through_seq >= 0), FOREIGN KEY(project_id,thread_id) REFERENCES threads(project_id,id), PRIMARY KEY(thread_id,actor_id));
CREATE TABLE requests (project_id TEXT NOT NULL REFERENCES projects(id), actor_id TEXT NOT NULL, operation TEXT NOT NULL, request_key TEXT NOT NULL, payload_hash TEXT NOT NULL, result TEXT NOT NULL CHECK(json_valid(result)), PRIMARY KEY(project_id,actor_id,operation,request_key));
CREATE INDEX messages_thread ON messages(project_id,thread_id,seq);
CREATE INDEX sources_project ON sources(project_id,blob_hash);
CREATE INDEX jobs_queue ON jobs(status,created_at);
CREATE INDEX decisions_current ON decisions(project_id,thread_id,stable_id,version);
CREATE INDEX constraints_current ON constraints(project_id,thread_id,stable_id,version);
